insert into k values ('Біла емаль','OUTSIDE','https://korfad.com.ua/content/images/47/278x600l80mc0/dverne-polotno-brillar-800-kh-2000-bila-emal-73147145778313.webp','https://korfad.com.ua/dverne-polotno-brillar-800-kh-2000-bila-emal/',1),('Біла емаль','INSIDE','https://korfad.com.ua/content/images/2/278x600l80mc0/dverne-polotno-brillar-800-kh-2010-bila-emal-inside-12325802427332.webp','https://korfad.com.ua/dverne-polotno-brillar-800-kh-2010-bila-emal-inside/',2);
insert into public.products(slug,category,brand,collection,name,material,style,color,price,description,features,image_path,sort_order,is_available) select 'korfad-ex-brillar','interior','KORFAD','EXELLENCE','KORFAD BRILLAR','Фарбоване покриття','Сучасний','Біла емаль','Ціна за запитом','KORFAD BRILLAR — фарбовані міжкімнатні двері колекції EXELLENCE. Доступні виконання OUTSIDE або INSIDE; точну комплектацію й ціну уточнюйте у менеджера.',jsonb_build_array('Фабрика KORFAD','Колекція EXELLENCE'),min(i),99999,false from k on conflict(slug) do update set name=excluded.name,description=excluded.description,image_path=excluded.image_path;
insert into public.product_options(product_slug,option_group,group_label,label,sort_order) values('korfad-ex-brillar','configuration','Відкривання','OUTSIDE',10),('korfad-ex-brillar','configuration','Відкривання','INSIDE',20) on conflict(product_slug,option_group,label) do update set sort_order=excluded.sort_order,is_active=true;
insert into public.product_variants(product_slug,selections,image_path,sort_order,is_active) select 'korfad-ex-brillar',jsonb_build_object('configuration',o),i,n,true from k on conflict(product_slug,selections) do update set image_path=excluded.image_path,sort_order=excluded.sort_order,is_active=true;
insert into public.product_media(product_slug,kind,label,image_path,sort_order) select 'korfad-ex-brillar','gallery',o,i,n from k source where not exists(select 1 from public.product_media m where m.product_slug='korfad-ex-brillar' and m.kind='gallery' and m.image_path=source.i);
